<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thông tin cá nhân</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-badge"><img src="/assets/pics/logo.webp" class="brand-logo" alt="Logo"></div><div><div class="brand-title">Trọ Tốt</div><div class="brand-subtitle">Management System</div></div></div><div class="user-mini sidebar-top"><div class="avatar"><?=htmlspecialchars(mb_substr($user['HoTen'],0,1))?></div><div class="user-info"><strong><?=htmlspecialchars($user['HoTen'])?></strong><small>nguoithue</small></div><a href="/logout.php" class="logout-btn"><i class="bi bi-box-arrow-right"></i></a></div><nav class="nav-menu"><a class="nav-item" href="/views/thongbao/index.php"><i class="bi bi-bell"></i> Thông báo</a><a class="nav-item active" href="/views/hoso/index.php"><i class="bi bi-person-circle"></i> Thông tin cá nhân</a><a class="nav-item" href="/views/hopdong/index.php"><i class="bi bi-file-text"></i> Hợp đồng</a><a class="nav-item" href="/views/chisodiennuoc/index.php"><i class="bi bi-lightning"></i> Điện / Nước</a><a class="nav-item" href="/views/hoadon/index.php"><i class="bi bi-receipt"></i> Hóa đơn</a><a class="nav-item" href="/views/suco/index.php"><i class="bi bi-tools"></i> Báo cáo sự cố</a><a class="nav-item" href="/views/tamtru/index.php"><i class="bi bi-person-vcard"></i> Khai báo lưu trú</a></nav></aside><main class="main-panel"><header class="topbar"><div><h2>Thông tin cá nhân</h2><p>Mọi thay đổi sẽ chờ chủ trọ xác nhận.</p></div></header><section class="card-panel"><form id="profileForm" class="row g-3"><div class="col-md-6"><label class="form-label">Họ tên</label><input id="HoTen" class="form-control" required></div><div class="col-md-6"><label class="form-label">CCCD</label><input id="CCCD" class="form-control" readonly></div><div class="col-md-6"><label class="form-label">Số điện thoại</label><input id="SoDienThoai" class="form-control"></div><div class="col-md-6"><label class="form-label">Email</label><input id="Email" type="email" class="form-control"></div><div class="col-12"><label class="form-label">Địa chỉ thường trú</label><input id="DiaChiThuongTru" class="form-control"></div><div class="col-md-6"><label class="form-label">Ảnh chân dung</label><input id="AnhChanDung" type="file" accept="image/*" class="form-control"></div><div class="col-md-6"><label class="form-label">CCCD mặt trước</label><input id="AnhCCCDMatTruoc" type="file" accept="image/*" class="form-control"></div><div class="col-md-6"><label class="form-label">CCCD mặt sau</label><input id="AnhCCCDMatSau" type="file" accept="image/*" class="form-control"></div><div class="col-md-6"><label class="form-label">VNeID mức 2</label><input id="VNeIDMuc2" type="file" accept="image/*" class="form-control"></div><div class="col-12"><button type="submit" class="btn btn-primary">Gửi chủ trọ xác nhận</button><span id="profileMessage" class="ms-2 small"></span></div></form></section></main></div><script src="/assets/js/app.js"></script><script>(()=>{const form=document.getElementById('profileForm'),msg=document.getElementById('profileMessage');let data={};const read=f=>new Promise(ok=>{if(!f)return ok(null);const r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(f)});window.app.api('/api/hoso.php').then(r=>{data=r.data||{};['HoTen','CCCD','SoDienThoai','Email','DiaChiThuongTru'].forEach(k=>document.getElementById(k).value=data[k]||'')}).catch(e=>msg.textContent=e.message);form.addEventListener('submit',async e=>{e.preventDefault();try{for(const k of ['AnhChanDung','AnhCCCDMatTruoc','AnhCCCDMatSau','VNeIDMuc2'])data[k]=await read(document.getElementById(k).files[0])||data[k]||null;for(const k of ['HoTen','SoDienThoai','Email','DiaChiThuongTru'])data[k]=document.getElementById(k).value;await window.app.api('/api/hoso.php',{method:'POST',body:JSON.stringify(data)});msg.className='ms-2 small text-success';msg.textContent='Đã gửi chủ trọ xác nhận.';}catch(err){msg.className='ms-2 small text-danger';msg.textContent=err.message;}})})();</script></body></html>
